<script setup lang="ts">
import AIButton from '../AIButton.vue'
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { onBeforeRouteLeave, onBeforeRouteUpdate, useRoute, useRouter } from 'vue-router'
import { useSettingsScope, useSettingsDialog } from '../settingsScope'
const { request:api }=useSettingsScope()
import { t, formatDate } from '../../i18n'
import { useLayoutBoolean } from '../../layoutScope'
import { useWorkspaceStore } from '../../stores/workspace'
import { memberHasProjectRole } from '../../memberRoles'
import AppSelect from '../AppSelect.vue'
import Icon from '../Icon.vue'
import SidebarCollapseButton from '../SidebarCollapseButton.vue'
import MemberMultiSelect from '../MemberMultiSelect.vue'
import RequirementPicker, { type RequirementChoice } from '../RequirementPicker.vue'
import RequirementAITestCases from '../RequirementAITestCases.vue'
import CustomFieldInputs from '../CustomFieldInputs.vue'
import QualityComments from '../QualityComments.vue'
import ResizableDrawer from '../ResizableDrawer.vue'
import TestCaseAIReview from './TestCaseAIReview.vue'
import { testingEditable,caseStepMove, folderRows, testCaseTypes, testCaseStates, testPositiveID, testTone, type TestCaseRecord, type TestFolder, type TestWorkspace, type TestMetadata } from '../../testingWorkspace'

const props=defineProps<{ workspace:TestWorkspace; members:any[]; executions:any[]; embedded?:boolean; requirementId?:number; initialCaseId?:number|null; linkExisting?:boolean }>()
const emit=defineEmits<{ refresh:[]; close:[] }>()
const route=useRoute(),router=useRouter(),session=useWorkspaceStore()
const libraryId=ref(0),folderId=ref<number|null>(null),folderQuery=ref(''),expanded=ref(new Set<number>())
const search=ref(''),status=ref(''),priority=ref(''),caseType=ref(''),owner=ref(''),page=ref(1),pageSize=ref(20)
const items=ref<TestCaseRecord[]>([]),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),notice=ref(''),selected=ref<number[]>([])
const libraryRailExpanded=useLayoutBoolean('testing.library.sidebar',true)
let requestVersion=0,detailVersion=0,searchTimer:ReturnType<typeof setTimeout>|undefined
const writable=computed(()=>props.workspace.canEdit&&!session.operationDisabled&&!session.identityConflict)
const library=computed(()=>props.workspace.libraries.find(x=>x.id===libraryId.value))
const tree=computed(()=>folderRows(props.workspace.folders,libraryId.value,expanded.value,folderQuery.value))
const folder=computed(()=>props.workspace.folders.find(x=>x.id===folderId.value))
const maxPage=computed(()=>Math.max(1,Math.ceil(total.value/pageSize.value)))
const allSelected=computed(()=>items.value.length>0&&items.value.every(x=>selected.value.includes(x.id)))
const requirementFilter=computed(()=>props.embedded?testPositiveID(props.requirementId):testPositiveID(route.query.requirement))
const opts=(values:string[],all:string)=>[{value:'',label:t(all)},...values.map(x=>({value:x,label:t(x)}))]
const libraryOptions=computed(()=>props.workspace.libraries.map(x=>({value:x.id,label:x.name})))
const ownerOptions=computed(()=>[{value:'',label:t('所有负责人')},...props.members.filter(x=>x.active).map(x=>({value:x.id,label:x.name}))])
const locationOptions=computed(()=>[{value:0,label:t('库根目录')},...folderRows(props.workspace.folders,location.libraryId,new Set(props.workspace.folders.map(x=>x.id))).map(x=>({value:x.id,label:'　'.repeat(x.depth)+x.name}))])
const editFolderOptions=computed(()=>[{value:0,label:t('库根目录')},...folderRows(props.workspace.folders,edit.metadata.libraryId||libraryId.value,new Set(props.workspace.folders.map(x=>x.id))).map(x=>({value:x.id,label:'　'.repeat(x.depth)+x.name}))])
const visibleField=(key:string)=>props.workspace.settings.fields.find(f=>f.key===key)?.enabled!==false
const requiredField=(key:string)=>props.workspace.settings.fields.some(f=>f.key===key&&f.enabled&&f.required)
const fieldDefault=(key:string)=>props.workspace.settings.fields.find(f=>f.key===key)?.defaultValue
const listFields=computed(()=>props.workspace.settings.fields.filter(f=>f.enabled&&f.listVisible&&f.key!=='requirementId'))
const showRequirementColumn=computed(()=>props.workspace.settings.fields.find(f=>f.key==='requirementId')?.listVisible!==false&&visibleField('requirementId'))
function listValue(item:TestCaseRecord,key:string){const value=key==='preconditions'?item.preconditions:(item.metadata as unknown as Record<string,unknown>)?.[key];return value===null||value===undefined||value===''?'—':String(value)}

async function load(){
  if(props.embedded||!libraryId.value)return
  const sequence=++requestVersion;loading.value=true;error.value=''
  const query=new URLSearchParams({page:String(page.value),pageSize:String(pageSize.value)})
  if(!requirementFilter.value||folderId.value)query.set('libraryId',String(libraryId.value))
  for(const [key,value] of Object.entries({q:search.value.trim(),status:status.value,priority:priority.value,caseType:caseType.value,ownerUserId:owner.value,requirementId:requirementFilter.value,folderId:folderId.value}))if(value!==''&&value!==null)query.set(key,String(value))
  try{const result=await api<{items:TestCaseRecord[];total:number}>(`/test-cases?${query}`);if(sequence!==requestVersion)return;items.value=result.items||[];total.value=result.total??items.value.length;selected.value=selected.value.filter(id=>items.value.some(x=>x.id===id));if(page.value>maxPage.value)page.value=maxPage.value}
  catch(cause){if(sequence===requestVersion)error.value=message(cause)}finally{if(sequence===requestVersion)loading.value=false}
}
function message(cause:unknown){return cause instanceof Error?cause.message:t('操作失败，请稍后重试')}
function resetPage(){page.value=1;selected.value=[];void load()}
watch(search,()=>{clearTimeout(searchTimer);searchTimer=setTimeout(resetPage,250)})
watch([status,priority,caseType,owner,folderId,pageSize],resetPage)
watch(page,load)
watch(()=>props.workspace.libraries,()=>{if(!props.workspace.libraries.some(x=>x.id===libraryId.value))libraryId.value=props.workspace.libraries.find(x=>x.isDefault)?.id||props.workspace.libraries[0]?.id||0;void load()},{immediate:true})
watch(libraryId,()=>{folderId.value=null;expanded.value=new Set();resetPage()})
function toggleFolder(id:number){const next=new Set(expanded.value);next.has(id)?next.delete(id):next.add(id);expanded.value=next}
function selectFolder(value:number|null){folderId.value=value}
function toggleSelect(id:number){selected.value=selected.value.includes(id)?selected.value.filter(x=>x!==id):[...selected.value,id]}
function toggleAll(){selected.value=allSelected.value?[]:items.value.map(x=>x.id)}
function resetFilters(){search.value='';status.value='';priority.value='';caseType.value='';owner.value='';page.value=1;void load()}

// 管理窗口统一接收稳定目录 ID；改名不改变用例归属，跨库移动由服务端原子校验。
const manager=ref<'library'|'folder'|'move'|null>(null),managerId=ref<number|null>(null)
const location=reactive({name:'',libraryId:0,folderId:0})
function manage(kind:'library'|'folder'|'move',existing?:TestFolder){if(!writable.value)return;manager.value=kind;managerId.value=existing?.id||null;Object.assign(location,{name:existing?.name||'',libraryId:libraryId.value,folderId:existing?(existing.parentId||0):(folderId.value||0)});error.value=''}
async function saveManager(){if(saving.value)return;saving.value=true;error.value='';try{
  if(manager.value==='move')await api('/testing/cases/move',{method:'POST',body:JSON.stringify({caseIds:selected.value,libraryId:location.libraryId,folderId:location.folderId||null})})
  else if(manager.value==='library')await api('/testing/libraries',{method:'POST',body:JSON.stringify({name:location.name})})
  else await api('/testing/folders'+(managerId.value?`/${managerId.value}`:''),{method:managerId.value?'PATCH':'POST',body:JSON.stringify({name:location.name,libraryId:location.libraryId,parentId:location.folderId||null})})
  manager.value=null;selected.value=[];notice.value=t('保存成功');emit('refresh');await load()
}catch(cause){error.value=message(cause)}finally{saving.value=false}}
async function deleteFolder(){if(!folder.value||!window.confirm(t('删除空目录“{name}”？',{name:folder.value.name})))return;saving.value=true;error.value='';try{await api(`/testing/folders/${folder.value.id}`,{method:'DELETE'});folderId.value=null;emit('refresh')}catch(cause){error.value=message(cause)}finally{saving.value=false}}

type Editable = Omit<TestCaseRecord,'id'|'code'|'updatedAt'|'metadata'|'customFields'> & {metadata:TestMetadata;customFields:Record<string,unknown>}
const empty=():Editable=>({title:'',category:'未分类',preconditions:'',steps:'',expected:'',priority:'P1',status:'草稿',caseType:'功能测试',owner:'',ownerUserId:'',enabled:true,tags:'',requirementId:null,stepsDetail:[{order:1,action:'',expected:''}],metadata:{description:'',testData:'',estimatedMinutes:0,libraryId:libraryId.value||null,folderId:folderId.value},customFields:{}})
const edit=reactive<Editable>(empty()),opened=ref(false),record=ref<TestCaseRecord|null>(null),detailTab=ref('details'),drawerWidth=ref(1120),baseline=ref(''),reviewComment=ref(''),reviews=ref<any[]>([]),activities=ref<any[]>([]),detailLoading=ref(false),datesValid=ref(true)
const comments=ref<InstanceType<typeof QualityComments>|null>(null),reviewBusy=ref(false)
// 内层用例抽屉先处理 Esc 并循环焦点，不让按键穿透关闭外层需求详情。
const embeddedDialog=useSettingsDialog(computed(()=>!!props.embedded&&opened.value),()=>close())
const dirty=computed(()=>opened.value&&!detailLoading.value&&JSON.stringify(edit)!==baseline.value)
const executionHistory=computed(()=>props.executions.filter(x=>x.caseId===record.value?.id))
const canReview=computed(()=>writable.value&&(props.workspace.canManage||memberHasProjectRole(session.currentUser,['qa'])))
const selectedRequirement=ref<RequirementChoice|null>(null)
function syncRecord(item:TestCaseRecord|null){Object.assign(edit,testingEditable(empty(),item));edit.metadata={description:item?.metadata?.description||'',testData:item?.metadata?.testData||'',estimatedMinutes:item?.metadata?.estimatedMinutes||0,libraryId:item?.metadata?.libraryId||libraryId.value||null,folderId:item?.metadata?.folderId||null};edit.stepsDetail=item?.stepsDetail?.length?item.stepsDetail.map(s=>({...s})):[{order:1,action:item?.steps||'',expected:item?.expected||''}];edit.customFields={...item?.customFields};record.value=item;selectedRequirement.value=item?.requirement||null;baseline.value=JSON.stringify(edit);datesValid.value=true}
function canLeave(){return !saving.value&&!reviewBusy.value&&comments.value?.canLeave()!==false&&(!dirty.value||window.confirm(t('放弃尚未保存的用例修改？')))}
async function createCase(){if(!writable.value||!canLeave())return;const sequence=++detailVersion;detailLoading.value=false;record.value=null;syncRecord(null);for(const key of ['description','testData','estimatedMinutes'] as const){const value=fieldDefault(key);if(value!==undefined&&value!==null)(edit.metadata as any)[key]=value}edit.preconditions=String(fieldDefault('preconditions')||'');edit.requirementId=requirementFilter.value||testPositiveID(fieldDefault('requirementId'));detailTab.value='details';opened.value=true;baseline.value=JSON.stringify(edit);if(edit.requirementId)try{const selected=await api<RequirementChoice>(`/requirements/${edit.requirementId}`);if(sequence===detailVersion&&opened.value&&edit.requirementId===selected.id)selectedRequirement.value=selected}catch(cause){if(sequence===detailVersion)error.value=message(cause)}}
async function openCase(id:number,push=true){if(push&&!props.embedded){await router.replace({query:{...route.query,tab:'cases',case:id,create:undefined}});return}const sequence=++detailVersion;detailLoading.value=true;opened.value=true;record.value=null;reviews.value=[];activities.value=[];detailTab.value='details';error.value='';try{const item=await api<TestCaseRecord>(`/test-cases/${id}`);if(sequence===detailVersion){
 if(props.embedded&&props.requirementId&&item.requirementId!==props.requirementId&&(!props.linkExisting||item.requirementId))throw Error('该用例的需求关联已变化，请刷新后重试')
 syncRecord(item)
 if(props.embedded&&props.linkExisting){edit.requirementId=props.requirementId||null;const requirement=await api<RequirementChoice>(`/requirements/${props.requirementId}`);if(sequence===detailVersion)selectedRequirement.value=requirement}
 }}catch(cause){if(sequence===detailVersion){error.value=message(cause);opened.value=false}}finally{if(sequence===detailVersion)detailLoading.value=false}}
async function close(){if(!canLeave())return;++detailVersion;opened.value=false;baseline.value=JSON.stringify(edit);if(props.embedded){emit('close');return}await router.replace({query:{...route.query,case:undefined,create:undefined}})}
function moveStep(index:number,direction:number){edit.stepsDetail=caseStepMove(edit.stepsDetail,index,direction)}
function addStep(){edit.stepsDetail.push({order:edit.stepsDetail.length+1,action:'',expected:''})}
function removeStep(index:number){if(edit.stepsDetail.length===1)return;edit.stepsDetail.splice(index,1);edit.stepsDetail.forEach((s,i)=>s.order=i+1)}
async function saveCase(){if(saving.value||!writable.value)return;error.value='';if(!edit.title.trim()){error.value=t('请填写用例标题');return}if(!edit.stepsDetail.length||edit.stepsDetail.some(s=>!s.action.trim()||!s.expected.trim())){error.value=t('每个步骤都需要操作描述和可验证的预期结果');return}if(!datesValid.value){error.value=t('请先修正日期输入');return}
  // 需求内编辑携带原关联条件，由服务端在事务中校验，避免覆盖其他人刚刚调整的关联。
  const payload=props.embedded&&record.value?{...edit,expectedRequirementId:record.value.requirementId??null}:edit
  saving.value=true;try{const next=await api<TestCaseRecord>(record.value?`/test-cases/${record.value.id}`:'/test-cases',{method:record.value?'PATCH':'POST',body:JSON.stringify(payload)});syncRecord(next);notice.value=t('用例已保存');emit('refresh');await load();opened.value=false;saving.value=false;if(props.embedded){emit('close');return}await router.replace({query:{...route.query,case:undefined,create:undefined}})}catch(cause){error.value=message(cause)}finally{saving.value=false}}
async function copyCase(){if(!record.value||!canLeave())return;saving.value=true;try{const next=await api<TestCaseRecord>(`/test-cases/${record.value.id}/copy`,{method:'POST'});syncRecord(next);await load();emit('refresh');saving.value=false;if(!props.embedded)await router.replace({query:{...route.query,case:next.id}})}catch(cause){error.value=message(cause)}finally{saving.value=false}}
async function loadDetailTab(){if(!record.value)return;const id=record.value.id,sequence=detailVersion;try{if(detailTab.value==='review'){const data=await api<any>(`/testing/cases/${id}/reviews`);if(sequence===detailVersion)reviews.value=data.items||[]}if(detailTab.value==='changes'){const data=await api<any>(`/testing/cases/${id}/history`);if(sequence===detailVersion)activities.value=data.items||[]}}catch(cause){error.value=message(cause)}}
function changeDetailTab(key:string){if(saving.value||reviewBusy.value||comments.value?.canLeave()===false)return;detailTab.value=key}
function reviewLabel(value:string){return value==='submit'?t('提交评审'):value==='approve'?t('评审通过'):value==='reject'?t('退回修改'):t(value)}
watch(detailTab,loadDetailTab)
async function review(decision:string){if(!record.value||saving.value||dirty.value||!writable.value||decision!=='submit'&&!canReview.value)return;saving.value=true;error.value='';try{await api(`/testing/cases/${record.value.id}/reviews`,{method:'POST',body:JSON.stringify({decision,comment:reviewComment.value})});syncRecord(await api<TestCaseRecord>(`/test-cases/${record.value.id}`));reviewComment.value='';await loadDetailTab();await load();emit('refresh')}catch(cause){error.value=message(cause)}finally{saving.value=false}}

const aiOpen=ref(false),aiBusy=ref(false),aiRequirement=ref<RequirementChoice|null>(null),aiRequirementVersion=ref(''),generator=ref<InstanceType<typeof RequirementAITestCases>|null>(null)
async function aiChoose(value:RequirementChoice|null){aiRequirement.value=value;aiRequirementVersion.value='';if(value){try{const saved=await api<any>(`/requirements/${value.id}`);if(aiRequirement.value?.id===value.id){aiRequirement.value=saved;aiRequirementVersion.value=saved.updatedAt}}catch(cause){error.value=message(cause)}}}
function closeAI(){if(aiBusy.value||generator.value?.canLeave()===false)return;aiOpen.value=false}
function imported(){aiOpen.value=false;notice.value=t('AI 用例已导入为草稿，可在用例库评审和完善');emit('refresh');void load()}
async function showAI(){if(!writable.value)return;aiOpen.value=true;if(requirementFilter.value)try{await aiChoose(await api(`/requirements/${requirementFilter.value}`))}catch(cause){error.value=message(cause)}}
watch(()=>route.query.case,value=>{if(props.embedded)return;const id=testPositiveID(value);if(id)void openCase(id,false);else if(route.query.create!=='1')opened.value=false},{immediate:true})
watch(()=>route.query.create,value=>{if(props.embedded)return;if(value==='1')void createCase()},{immediate:true})
watch(requirementFilter,resetPage)
onBeforeRouteLeave(()=>canLeave()&&!aiBusy.value&&generator.value?.canLeave()!==false)
onBeforeRouteUpdate(to=>{if(aiBusy.value||saving.value||reviewBusy.value)return false;if(to.query.case!==route.query.case||to.query.tab!==route.query.tab||to.query.create!==route.query.create||to.query.requirement!==route.query.requirement)return canLeave()&&generator.value?.canLeave()!==false;return true})
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value||aiBusy.value||reviewBusy.value||saving.value){event.preventDefault();event.returnValue=''}}
window.addEventListener('beforeunload',beforeUnload)
onBeforeUnmount(()=>{requestVersion++;detailVersion++;clearTimeout(searchTimer);window.removeEventListener('beforeunload',beforeUnload)})
// 嵌入需求详情时，不读取或改写外层路由，取消只关闭用例抽屉。
watch(()=>props.initialCaseId,()=>{if(props.embedded){if(props.initialCaseId)void openCase(props.initialCaseId,false);else void createCase()}},{immediate:true})
defineExpose({refresh:load,create:createCase,canLeave})
</script>

<template>
  <section :class="embedded?'test-case-embedded':'test-library'">
    <p v-if="embedded&&error&&!opened" class="test-error" role="alert">{{error}} <button class="btn" @click="emit('close')">{{t('关闭')}}</button></p>
    <aside v-if="!embedded" class="test-library-rail" :class="{'is-collapsed':!libraryRailExpanded}">
      <SidebarCollapseButton :expanded="libraryRailExpanded" :label="t('测试用例侧边栏')" @toggle="libraryRailExpanded=!libraryRailExpanded"/>
      <div v-show="libraryRailExpanded" class="test-library-rail-content">
      <div class="test-rail-heading"><span class="test-rail-icon"><Icon name="folder" :size="18"/></span><div><strong>{{t('用例资产')}}</strong><small>{{t('按业务模块组织与复用')}}</small></div></div>
      <div class="test-library-choice"><AppSelect v-model="libraryId" :options="libraryOptions" :label="t('选择用例库')"/><button class="test-icon-button" :disabled="!writable" :title="t('创建用例库')" :aria-label="t('创建用例库')" @click="manage('library')">＋</button></div>
      <div class="test-rail-search"><Icon name="search" :size="14"/><input v-model="folderQuery" :placeholder="t('搜索目录')" :aria-label="t('搜索目录')"/></div>
      <button :class="['test-tree-all',{active:folderId===null}]" @click="selectFolder(null)"><Icon name="list" :size="15"/><span>{{t('全部用例')}}</span><small>{{library?.count||0}}</small></button>
      <div class="test-tree" role="tree" :aria-label="t('用例目录')">
        <div v-for="node in tree" :key="node.id" :class="['test-tree-row',{active:folderId===node.id}]" :style="{'--depth':node.depth}">
          <button class="test-tree-toggle" :disabled="!node.hasChildren" :aria-label="t(expanded.has(node.id)?'收起目录':'展开目录')" :aria-expanded="node.hasChildren?expanded.has(node.id):undefined" @click="toggleFolder(node.id)">{{node.hasChildren?(expanded.has(node.id)?'⌄':'›'):'·'}}</button>
          <button class="test-tree-name" role="treeitem" :aria-selected="folderId===node.id" :title="node.name" @click="selectFolder(node.id)"><Icon name="folder" :size="14"/><span>{{node.name}}</span><small>{{node.count}}</small></button>
        </div>
        <p v-if="!tree.length" class="test-rail-empty">{{folderQuery?t('未找到匹配目录'):t('创建目录，整理你的第一组用例')}}</p>
      </div>
      <button class="test-add-folder" :disabled="!writable" @click="manage('folder')">＋ {{t('创建目录')}}</button>
      <div class="test-rail-foot"><Icon name="work" :size="15"/><p>{{t('用例经评审后加入测试计划，执行记录持续保留。')}}</p></div>
      </div>
    </aside>
    <main v-if="!embedded" class="test-library-main">
      <header class="test-content-heading"><div><div class="test-breadcrumb">{{library?.name}} <span>/</span> {{folder?.name||t('全部用例')}}</div><h2>{{folder?.name||t('测试用例')}}<span class="test-count">{{total}}</span></h2></div><div class="test-actions"><template v-if="folder"><button class="test-subtle" :disabled="!writable" @click="manage('folder',folder)">{{t('编辑目录')}}</button><button class="test-subtle" :disabled="!writable||saving" @click="deleteFolder">{{t('删除空目录')}}</button></template><AIButton :disabled="!writable" @click="showAI">{{t('AI 生成用例')}}</AIButton><button class="btn primary" :disabled="!writable" @click="createCase">＋ {{t('创建用例')}}</button></div></header>
      <p v-if="requirementFilter" class="test-context-note">{{t('当前仅显示与所选需求关联的用例')}}<button class="link" @click="router.replace({query:{...route.query,requirement:undefined}})">{{t('查看全部')}}</button></p>
      <div class="test-filter-bar"><div class="test-search"><Icon name="search" :size="16"/><input v-model="search" type="search" :placeholder="t('搜索编号、标题或标签')" :aria-label="t('搜索编号、标题或标签')"/></div><AppSelect v-model="priority" :options="opts(['P0','P1','P2','P3'],'全部优先级')" :label="t('优先级筛选')"/><AppSelect v-model="caseType" :options="opts(testCaseTypes,'全部类型')" :label="t('用例类型筛选')"/><AppSelect v-model="status" :options="opts(testCaseStates,'全部评审状态')" :label="t('评审状态筛选')"/><div class="test-owner-filters"><AppSelect v-model="owner" :options="ownerOptions" :label="t('负责人筛选')"/><button :class="['test-filter-mine',{active:owner===session.currentUser?.id}]" @click="owner=owner===session.currentUser?.id?'':session.currentUser?.id||''">{{t('我负责的')}}</button></div><button v-if="search||status||priority||caseType||owner" class="test-subtle" @click="resetFilters">{{t('重置')}}</button></div>
      <p v-if="error&&!opened&&!manager&&!aiOpen" class="test-error" role="alert">{{error}}<button class="link" @click="load">{{t('重试')}}</button></p><p v-if="notice" class="test-notice" role="status">{{notice}}</p>
      <div v-if="selected.length" class="test-selection"><strong>{{t('已选择 {count} 个用例',{count:selected.length})}}</strong><button class="btn" :disabled="!writable" @click="manage('move')">{{t('移动到目录')}}</button><button class="test-subtle" @click="selected=[]">{{t('取消选择')}}</button></div>
      <div class="test-table-frame" :aria-busy="loading"><table class="test-table case-table"><thead><tr><th class="test-check"><input type="checkbox" :checked="allSelected" :aria-label="t('选择当前页全部用例')" @change="toggleAll"/></th><th>{{t('用例名称')}}</th><th>{{t('等级')}}</th><th>{{t('类型')}}</th><th>{{t('评审状态')}}</th><th>{{t('负责人')}}</th><th v-if="showRequirementColumn">{{t('关联需求')}}</th><th v-for="field in listFields" :key="field.key">{{t(field.name)}}</th><th>{{t('更新时间')}}</th></tr></thead><tbody>
        <tr v-for="item in items" :key="item.id" :class="{'is-selected':selected.includes(item.id)}"><td class="test-check"><input type="checkbox" :checked="selected.includes(item.id)" :aria-label="t('选择用例')+' '+item.code" @change="toggleSelect(item.id)"/></td><td class="test-name"><button @click="openCase(item.id)"><span class="test-case-icon"><Icon name="review" :size="15"/></span><span><strong>{{item.title}}</strong><small>{{item.code}}<span v-if="item.tags"> · {{item.tags}}</span><span v-if="!item.enabled"> · {{t('已停用')}}</span></small></span></button></td><td><span :class="['test-badge',testTone(item.priority)]">{{item.priority}}</span></td><td><span :class="['test-badge',testTone(item.caseType)]">{{t(item.caseType)}}</span></td><td><span :class="['test-badge',testTone(item.status)]"><i/>{{t(item.status)}}</span></td><td><span v-if="item.owner" class="test-owner"><span>{{item.owner.slice(0,1)}}</span>{{item.owner}}</span><span v-else class="test-muted">—</span></td><td v-if="showRequirementColumn"><router-link v-if="item.requirement" class="test-requirement-link" :to="`/requirements?req=${item.requirement.id}`" :title="item.requirement.title">{{item.requirement.code}}</router-link><span v-else class="test-muted">—</span></td><td v-for="field in listFields" :key="field.key" class="test-ellipsis" :title="listValue(item,field.key)">{{listValue(item,field.key)}}</td><td class="test-date">{{formatDate(item.updatedAt)}}</td></tr>
        <tr v-if="!items.length"><td :colspan="7+(showRequirementColumn?1:0)+listFields.length"><div class="test-empty"><span class="test-empty-icon"><Icon name="folder" :size="30"/></span><h3>{{loading?t('正在加载…'):t('这里还没有测试用例')}}</h3><p>{{t('选择需求后使用 AI 辅助生成，或从一个清晰可执行的步骤开始。')}}</p><button v-if="!loading" class="btn primary" :disabled="!writable" @click="createCase">＋ {{t('创建用例')}}</button></div></td></tr>
      </tbody></table></div>
      <footer class="test-pagination"><span>{{t('共 {count} 条',{count:total})}}<span v-if="total"> · {{(page-1)*pageSize+1}}–{{Math.min(page*pageSize,total)}}</span></span><div><span>{{t('每页')}}</span><AppSelect v-model="pageSize" :options="[20,50,100].map(value=>({value,label:String(value)}))" :label="t('每页条数')"/><button class="test-page-button" :disabled="page<=1||loading" :aria-label="t('上一页')" @click="page--">‹</button><span>{{page}} / {{maxPage}}</span><button class="test-page-button" :disabled="page>=maxPage||loading" :aria-label="t('下一页')" @click="page++">›</button></div></footer>
    </main>
    <div v-if="opened" ref="embeddedDialog" tabindex="-1" class="drawer-shade" @click.self="close"><ResizableDrawer v-model:width="drawerWidth" storage-key="testing.case.workspace.width" :initial-width="1120" :min-width="680" :label="record?.title||t('创建用例')" class="test-case-drawer"><header class="test-drawer-header"><div><span class="test-breadcrumb">{{record?.code||t('新建测试用例')}}</span><h2>{{record?.title||t('创建测试用例')}}</h2></div><div class="test-actions"><button v-if="record" class="btn" :disabled="saving||!writable" @click="copyCase">{{t('复制')}}</button><button class="test-icon-button" :aria-label="t('关闭详情')" :disabled="saving||reviewBusy" @click="close">×</button></div></header><nav v-if="record" class="test-detail-tabs"><button v-for="x in [{key:'details',label:'详细信息'},{key:'review',label:'评审'},{key:'executions',label:'执行与缺陷'},{key:'changes',label:'变更记录'}]" :key="x.key" :class="{active:detailTab===x.key}" :disabled="saving||reviewBusy" @click="changeDetailTab(x.key)">{{t(x.label)}}</button></nav>
      <p v-if="error" class="test-error" role="alert">{{error}}</p><p v-if="detailLoading" class="test-notice">{{t('正在加载…')}}</p>
      <form v-if="detailTab==='details'&&!detailLoading" class="test-editor" @submit.prevent="saveCase"><div class="test-editor-content"><fieldset :disabled="saving||!writable"><label class="test-field">{{t('用例标题')}} *<input v-model="edit.title" maxlength="200" required :placeholder="t('例如：无权限成员访问受限需求时被拒绝')"/></label><label v-if="visibleField('description')" class="test-field"><span>{{t('用例描述')}}<b v-if="requiredField('description')"> *</b></span><textarea v-model="edit.metadata.description" rows="3" :required="requiredField('description')" :placeholder="t('说明测试目标、覆盖范围和风险')"/></label><div class="test-two-columns"><label v-if="visibleField('preconditions')" class="test-field"><span>{{t('前置条件')}}<b v-if="requiredField('preconditions')"> *</b></span><textarea v-model="edit.preconditions" rows="3" :required="requiredField('preconditions')" :placeholder="t('账号权限、环境状态及必要准备')"/></label><label v-if="visibleField('testData')" class="test-field"><span>{{t('测试数据')}}<b v-if="requiredField('testData')"> *</b></span><textarea v-model="edit.metadata.testData" rows="3" :required="requiredField('testData')" :placeholder="t('明确输入值、边界值和数据准备')"/></label></div><div class="test-section-title"><h3>{{t('步骤与预期')}}</h3><span>{{t('每一步都有可验证的结果')}}</span></div><div class="test-steps-table"><div class="test-step-head"><span>#</span><span>{{t('操作步骤')}}</span><span>{{t('预期结果')}}</span><span/></div><div v-for="(step,index) in edit.stepsDetail" :key="index" class="test-step-row"><span class="test-step-index">{{index+1}}</span><textarea v-model="step.action" rows="3" required :aria-label="t('操作步骤')+' '+(index+1)" :placeholder="t('输入具体操作')"/><textarea v-model="step.expected" rows="3" required :aria-label="t('预期结果')+' '+(index+1)" :placeholder="t('输入可观察、可判断的结果')"/><div class="test-step-actions"><button type="button" :disabled="index===0" :aria-label="t('上移步骤')" @click="moveStep(index,-1)">↑</button><button type="button" :disabled="index===edit.stepsDetail.length-1" :aria-label="t('下移步骤')" @click="moveStep(index,1)">↓</button><button type="button" :disabled="edit.stepsDetail.length===1" :aria-label="t('删除步骤')" @click="removeStep(index)">×</button></div></div></div><button type="button" class="test-add-step" @click="addStep">＋ {{t('添加步骤')}}</button><CustomFieldInputs object-type="test_case" v-model="edit.customFields" :members="members" :disabled="saving||!writable" @validity-change="datesValid=$event"/></fieldset><QualityComments v-if="record" ref="comments" :key="record.id" resource="test-cases" :object-id="record.id" :members="members" :disabled="saving||!writable"/></div><aside class="test-editor-props"><h3>{{t('用例属性')}}</h3><fieldset :disabled="saving||!writable"><label class="test-field">{{t('所在用例库')}}<AppSelect :model-value="edit.metadata.libraryId||libraryId" :options="libraryOptions" :label="t('所在用例库')" :disabled="saving||!writable" @update:model-value="edit.metadata.libraryId=Number($event);edit.metadata.folderId=null"/></label><label class="test-field">{{t('所在目录')}}<AppSelect :model-value="edit.metadata.folderId||0" :options="editFolderOptions" :label="t('所在目录')" :disabled="saving||!writable" @update:model-value="edit.metadata.folderId=Number($event)||null"/></label><label class="test-field">{{t('等级')}}<AppSelect v-model="edit.priority" :options="['P0','P1','P2','P3'].map(value=>({value,label:value}))" :label="t('等级')" :disabled="saving||!writable"/></label><label class="test-field">{{t('用例类型')}}<AppSelect v-model="edit.caseType" :options="testCaseTypes.map(value=>({value,label:t(value)}))" :label="t('用例类型')" :disabled="saving||!writable"/></label><MemberMultiSelect single :label="t('用例负责人')" :members="members" :model-value="edit.ownerUserId?[edit.ownerUserId]:[]" :legacy-name="edit.owner" :show-lead="false" :disabled="saving||!writable" @update:model-value="edit.ownerUserId=$event[0]||'';edit.owner=members.find(x=>x.id===$event[0])?.name||''"/><RequirementPicker v-if="visibleField('requirementId')" v-model="edit.requirementId" :label="t('关联需求')+(requiredField('requirementId')?' *':'')" :selected-requirement="selectedRequirement" :disabled="embedded||saving||!writable" @change="selectedRequirement=$event"/><label class="test-field">{{t('标签')}}<input v-model="edit.tags" :placeholder="t('冒烟、回归、核心流程')"/></label><label v-if="visibleField('estimatedMinutes')" class="test-field">{{t('预计执行时间（分钟）')}}<input type="number" v-model.number="edit.metadata.estimatedMinutes" :min="requiredField('estimatedMinutes')?1:0" max="10080" step="1" :required="requiredField('estimatedMinutes')"/></label><label class="test-check-label"><input type="checkbox" v-model="edit.enabled"/>{{t('启用用例')}}</label></fieldset><div class="test-helper">{{t('保存用例后提交评审；评审通过的用例可用于测试计划。')}}</div></aside><footer class="test-editor-footer" data-menu-boundary="bottom"><span>{{dirty?t('有未保存的修改'):t('内容已同步')}}</span><div><button type="button" class="btn" :disabled="saving" @click="close">{{t('取消')}}</button><button type="submit" class="btn primary" :disabled="saving||!writable">{{saving?t('保存中…'):t('保存用例')}}</button></div></footer></form>
      <section v-else-if="detailTab==='review'&&record" class="test-detail-content"><div class="test-section-title"><h3>{{t('人工评审')}}</h3><span :class="['test-badge',testTone(record.status)]">{{t(record.status)}}</span></div><p class="test-helper">{{t('评审关注可执行性、覆盖完整性及预期结果是否清晰。')}}</p><p v-if="dirty" class="test-error">{{t('请先保存用例内容，再提交评审。')}}</p><textarea v-model="reviewComment" class="test-review-comment" rows="3" :placeholder="t('填写评审意见，退回时请说明需要改进的内容')" :aria-label="t('评审意见')"/><div class="test-actions"><button v-if="record.status==='草稿'" class="btn primary" :disabled="saving||dirty||!writable" @click="review('submit')">{{t('提交评审')}}</button><template v-if="record.status==='待评审'"><button class="btn primary" :disabled="saving||dirty||!canReview" @click="review('approve')">{{t('评审通过')}}</button><button class="btn" :disabled="saving||dirty||!canReview||!reviewComment.trim()" @click="review('reject')">{{t('退回修改')}}</button></template></div><ol class="test-timeline"><li v-for="(item,i) in reviews" :key="item.id||i"><strong>{{item.actorName||item.actor||item.userName}}</strong><span>{{reviewLabel(item.decision||item.action||item.event)}} · {{formatDate(item.createdAt)}}</span><p>{{item.comment||item.detail}}</p></li></ol><TestCaseAIReview :case-id="record.id" :updated-at="record.updatedAt" :disabled="dirty||saving||!writable" @busy-change="reviewBusy=$event"/></section>
      <section v-else-if="detailTab==='executions'" class="test-detail-content"><h3>{{t('执行与缺陷')}}</h3><div class="test-table-frame"><table class="test-table"><thead><tr><th>{{t('测试计划')}}</th><th>{{t('执行结果')}}</th><th>{{t('执行人')}}</th><th>{{t('执行时间')}}</th><th>{{t('关联缺陷')}}</th></tr></thead><tbody><tr v-for="x in executionHistory" :key="x.id"><td><router-link :to="`/tests?tab=executions&execution=${x.id}`">{{x.planName}}</router-link></td><td><span :class="['test-badge',testTone(x.status)]">{{t(x.status)}}</span></td><td>{{x.executor||'—'}}</td><td>{{formatDate(x.executedAt)}}</td><td><router-link v-if="x.defectId" :to="`/defects?bug=${x.defectId}`">BUG-{{String(x.defectId).padStart(4,'0')}}</router-link><span v-else>—</span></td></tr><tr v-if="!executionHistory.length"><td colspan="5" class="test-empty-cell">{{t('尚未加入测试计划或执行')}}</td></tr></tbody></table></div></section>
      <section v-else-if="detailTab==='changes'" class="test-detail-content"><h3>{{t('变更记录')}}</h3><ol class="test-timeline"><li v-for="(item,i) in activities" :key="item.id||i"><strong>{{item.actorName||item.actor}}</strong><span>{{t(item.event||item.action)}} · {{formatDate(item.createdAt)}}</span><p>{{item.detail}}</p></li></ol><p v-if="!activities.length" class="test-helper">{{t('暂无变更记录')}}</p></section>
    </ResizableDrawer></div>
    <div v-if="manager" class="test-modal-shade slide-panel-shade" @click.self="!saving&&(manager=null)"><form class="test-modal" role="dialog" aria-modal="true" :aria-label="t(manager==='move'?'移动用例':manager==='library'?'创建用例库':managerId?'编辑目录':'创建目录')" @submit.prevent="saveManager"><header><h2>{{t(manager==='move'?'移动用例':manager==='library'?'创建用例库':managerId?'编辑目录':'创建目录')}}</h2><button type="button" class="test-icon-button" :disabled="saving" :aria-label="t('关闭')" @click="manager=null">×</button></header><div class="test-modal-body"><label v-if="manager!=='move'" class="test-field">{{t('名称')}} *<input v-model="location.name" required maxlength="100" autofocus/></label><template v-if="manager!=='library'"><label class="test-field">{{t('用例库')}}<AppSelect v-model="location.libraryId" :options="libraryOptions" :label="t('用例库')" :disabled="!!managerId||saving" @update:model-value="location.folderId=0"/></label><label class="test-field">{{t(manager==='move'?'目标目录':'上级目录')}}<AppSelect v-model="location.folderId" :options="locationOptions.filter(x=>x.value!==managerId)" :label="t('目标目录')" :disabled="saving"/></label></template><p v-if="error" class="test-error" role="alert">{{error}}</p></div><footer><button type="button" class="btn" :disabled="saving" @click="manager=null">{{t('取消')}}</button><button class="btn primary" :disabled="saving">{{t('保存')}}</button></footer></form></div>
    <div v-if="aiOpen" class="drawer-shade" @click.self="closeAI"><ResizableDrawer v-model:width="drawerWidth" storage-key="testing.ai.width" :initial-width="1000" :min-width="600" :label="t('AI 生成用例')" class="test-case-drawer"><header class="test-drawer-header"><div><span class="test-breadcrumb">{{library?.name}} / {{folder?.name||t('库根目录')}}</span><h2>✧ {{t('AI 生成用例')}}</h2></div><button class="test-icon-button" :disabled="aiBusy" :aria-label="t('关闭')" @click="closeAI">×</button></header><div class="test-detail-content"><p class="test-helper">{{t('关联已保存需求，生成后检查覆盖与步骤，选择需要的用例导入当前目录。')}}</p><RequirementPicker :model-value="aiRequirement?.id||null" :selected-requirement="aiRequirement" :label="t('生成依据：关联需求')" :disabled="aiBusy" @change="aiChoose"/><RequirementAITestCases v-if="aiRequirement&&aiRequirementVersion" ref="generator" :key="aiRequirement.id" :requirement-id="aiRequirement.id" :requirement-updated-at="aiRequirementVersion" :library-id="libraryId" :folder-id="folderId" @busy-change="aiBusy=$event" @imported="imported"/><p v-if="error" class="test-error" role="alert">{{error}}</p></div></ResizableDrawer></div>
  </section>
</template>
